package br.radaraero.widget;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.View;import android.widget.*;import org.json.*;
public class RadarWidget extends AppWidgetProvider {
 static final String PINNED="br.radaraero.widget.PINNED";
 static final String REFRESH="br.radaraero.widget.REFRESH";
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){drawAll(c,"Atualizando…");RefreshJob.schedule(c);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle opts){drawAll(c,"");}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(PINNED.equals(i.getAction())){drawAll(c,"");if(c.getSharedPreferences("radar",0).getString("point",null)!=null)RefreshJob.schedule(c);}if(REFRESH.equals(i.getAction())){drawAll(c,"Atualizando…");RefreshJob.schedule(c);}}
 static void drawAll(Context c,String status){AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,RadarWidget.class));android.content.SharedPreferences prefs=c.getSharedPreferences("radar",0);
 for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);String stamp="Sem consulta · adsb.lol";JSONArray rows=new JSONArray();JSONObject point=new JSONObject();long snapshotAt=0;try{point=new JSONObject(prefs.getString("point","{}"));JSONObject snap=new JSONObject(prefs.getString("snapshot","{}"));rows=snap.optJSONArray("rows");if(rows==null)rows=new JSONArray();long at=snap.optLong("at",0);snapshotAt=at;if(at>0)stamp=""+android.text.format.DateFormat.format("dd/MM HH:mm",at)+" · adsb.lol / adsbdb";}catch(Exception ignored){}
 int[] rowIds={R.id.row1,R.id.row2,R.id.row3};for(int n=0;n<3;n++){JSONObject row=rows.optJSONObject(n);v.setTextViewText(rowIds[n],row==null?(n==0?(point.has("lat")?"Nenhum avião recente na última consulta":"Toque em Ajustes para escolher seu ponto"):""):styledRow(row));v.setViewVisibility(rowIds[n],n==0||row!=null?View.VISIBLE:View.GONE);}int height=manager.getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,180);if(height<300)v.setViewVisibility(R.id.row2,View.GONE);if(height<390)v.setViewVisibility(R.id.row3,View.GONE);if(prefs.getInt("aircraftCount",3)==1){v.setViewVisibility(R.id.row2,View.GONE);v.setViewVisibility(R.id.row3,View.GONE);}boolean stale=snapshotAt>0&&System.currentTimeMillis()-snapshotAt>120000;v.setTextViewText(R.id.status,(status.isEmpty()?"":status+" · ")+(stale?"DADOS ANTIGOS · ":"")+stamp);v.setTextColor(R.id.status,stale?0xffefc479:0xff91aa9c);v.setViewVisibility(R.id.consultation_age,snapshotAt>0?View.VISIBLE:View.GONE);if(snapshotAt>0){long elapsed=Math.max(0,System.currentTimeMillis()-snapshotAt);v.setChronometer(R.id.consultation_age,android.os.SystemClock.elapsedRealtime()-elapsed,"Consulta há %s",true);}
 Intent refresh=new Intent(c,RadarWidget.class).setAction(REFRESH);v.setOnClickPendingIntent(R.id.refresh,PendingIntent.getBroadcast(c,1,refresh,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));Intent cfg=new Intent(c,ConfigureActivity.class);cfg.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);v.setOnClickPendingIntent(R.id.configure,PendingIntent.getActivity(c,id,cfg,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
 Intent open=new Intent(c,ConfigureActivity.class);String link=point.optString("radarUrl","");if(point.has("lat")&&(!link.startsWith("https://")||link.startsWith("https://radar-aero.e8zxc1.chatgpt.site")))link=ConfigureActivity.RADAR;if(link.startsWith("https://")){android.net.Uri u=android.net.Uri.parse(link);android.net.Uri.Builder b=u.buildUpon().clearQuery().appendQueryParameter("lat",point.optString("lat")).appendQueryParameter("lon",point.optString("lon")).appendQueryParameter("radiusKm",point.optString("radiusKm","10"));open=new Intent(Intent.ACTION_VIEW,b.build());}PendingIntent launch=PendingIntent.getActivity(c,id+10000,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.root,launch);v.setOnClickPendingIntent(R.id.open_radar,launch);for(int n=0;n<rowIds.length;n++){JSONObject row=rows.optJSONObject(n);Intent rowOpen=open;if(row!=null&&row.optString("id").matches("[a-f0-9]{6}")&&open.getData()!=null){android.net.Uri linkToAircraft=open.getData().buildUpon().appendQueryParameter("aircraft",row.optString("id")).build();rowOpen=new Intent(Intent.ACTION_VIEW,linkToAircraft);}PendingIntent rowLaunch=PendingIntent.getActivity(c,id*10+n+20000,rowOpen,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(rowIds[n],rowLaunch);}manager.updateAppWidget(id,v);}}
 static CharSequence styledRow(JSONObject row){if(!row.has("displayCall"))return row.optString("label");String head=(row.optString("company")+" "+row.optString("displayCall")).trim();String route=row.optString("route","Rota não informada");String distance=String.format(java.util.Locale.forLanguageTag("pt-BR"),"%.1f km",row.optDouble("distance"));String detail=distance+" · "+row.optString("model")+" · "+row.optString("altitude");boolean stale=System.currentTimeMillis()-row.optLong("positionAt",0)>120000;String text=head+"\n"+route+"\n"+detail+(stale?"\nPosição antiga · toque em Atualizar":"");android.text.SpannableString label=new android.text.SpannableString(text);label.setSpan(new android.text.style.StyleSpan(android.graphics.Typeface.BOLD),0,head.length(),33);label.setSpan(new android.text.style.ForegroundColorSpan(stale?0xffefc479:0xffb1f67a),head.length()+1,head.length()+1+route.length(),33);label.setSpan(new android.text.style.RelativeSizeSpan(.82f),head.length()+route.length()+2,text.length(),33);return label;}

}

